INSERT INTO knowledge_document(company_id,dept_id,title,doc_type,original_filename,security_level,content,uploader_user_id) VALUES(1,2,'云帆CRM续费与客户成功政策','业务政策','demo-policy.txt',1,'专业版标准续费价格1999元/月/企业。高价值客户到期前60天进入续费预警。近30天有P1/P2投诉、活跃度下降或提出竞品迁移意向时应升级客户成功经理。重大价格调整必须人工审批。',1),(1,2,'API稳定性SLA','SLA','demo-sla.txt',2,'P1重大接口故障15分钟受理，2小时内提供临时方案。P2核心接口异常30分钟受理，4小时内恢复。30天同一问题重复3次需专项根因分析。',1),(2,2,'企业专线服务标准','SLA','xl-sla.txt',1,'重大网络中断15分钟响应。重复故障、装机延期和SLA违约是离网高风险信号。竞品降价时需结合客户到期时间和历史投诉制定挽留方案。',1),(3,3,'促销与利润管理原则','经营制度','yg-profit.txt',1,'大促不能只看GMV，应同步监控毛利率、退货率、履约成本、会员留存和促销ROI。',1),(4,3,'制造项目交付风险SOP','SOP','hy-sop.txt',1,'交付延期超过7天、返工超过2次或大客户验收受阻时需升级项目风险。管理层介入前应汇总合同金额、延期原因、备件、投诉和应收状态。',1);
